import assert from 'node:assert/strict';import {Database} from 'bun:sqlite';import {readdir} from 'node:fs/promises';
const db=new Database(':memory:');db.exec(await Bun.file('order-tags.sql').text());
try{const keys=db.query('pragma table_info(order_tag)').all().filter(c=>c.pk);assert.equal(keys.length,1);assert.equal(keys[0].name,'order_tag_id');db.exec("insert into order_tag(order_tag_id,order_id,tag_id) values ('first','order','tag')");assert.throws(()=>db.exec("insert into order_tag(order_tag_id,order_id,tag_id) values ('second','order','tag')"),/UNIQUE constraint failed/);const names=(await readdir('migrations')).sort();const ids=names.map(n=>n.split('_')[0]);assert.equal(new Set(ids).size,ids.length);console.log('Independent live SQLite key/uniqueness and migration registry passed');}catch(error){if(error.code!=='ERR_ASSERTION')throw error;console.log(error);process.exitCode=10;}finally{db.close();}
